\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{tikzpicture}[scale=1]

\tkzDefPoint(0,0){O}
\tkzDefPoint(0:3.5){A}
\tkzDefPoint(30:3.5){B}
\tkzDefPoint(90:3){C}

\tkzMarkAngle[color=lightblue,fill=lightblue,size=1cm](A,O,B)
\tkzMarkAngle[color=orangepeel,fill=orangepeel,size=1cm](B,O,C)

\tkzDrawLines[very thick,add=0 and 0.2](O,A O,B O,C)

\tkzLabelAngle[pos=1.4](A,O,B){[math]30^\circ[/math]}
\tkzLabelAngle[pos=1.3](B,O,C){[math]60^\circ[/math]}

\end{tikzpicture}
\end{document}

For example, the angles in the diagram above are complementary because the sum of their measures is [math]90^\circ\mathbin{:}[/math]

\[
	60^\circ +30^\circ = 90^\circ
\]

