\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{tikzpicture}[]

\begin{scope}
\tkzDefPoint(0,0){O}
\tkzDefPoint(0:3){A}
\tkzDefPoint(37:3){B}
\tkzDefPoint(90:3){C}

\tkzMarkAngle[color=lightyellow,fill=lightyellow,size=1.2cm](A,O,B)
\tkzMarkAngle[color=lightblue,fill=lightblue,size=1.2cm](B,O,C)
\tkzMarkRightAngle[color=rustred,fill=rustred,size=0.5](A,O,C)

\tkzDrawLines[very thick, add=0 and 0.2](O,A O,B O,C)

\tkzLabelAngle[pos=1.5](A,O,B){[math]a[/math]}
\tkzLabelAngle[pos=1.5](B,O,C){[math]b[/math]}

\end{scope}

\end{tikzpicture}
\end{document}


Since [math]\angle a[/math] and [math]\angle b[/math] are complementary, the sum of their measures is equal to [math]90^\circ.[/math] So, we have:

\begin{align*}
	m\angle a + m \angle b &= 90^{\circ} \\[5pt]
	   37^\circ + m \angle b &= 90^{\circ} \\[5pt]
                            m \angle b &= 90^{\circ}-37^\circ \\[5pt]
                            m \angle b &= 53^\circ
\end{align*}

